// Attack level 20 dark wizard
const state = sdk.getState();
let target = null;
for (const npc of state.npcs) {
  if (npc.name.toLowerCase() === 'dark wizard' && npc.combatLevel === 20 && npc.reachable !== false) {
    target = npc;
    break;
  }
}

if (target) {
  console.log('Found reachable level 20 dark wizard:', target.name, 'level:', target.combatLevel);
  const result = await bot.attack(target);
  console.log('Attack result:', result);
} else {
  console.log('No reachable level 20 dark wizard');
}
